-- Пояснения к каждому варианту для прежних вопросов тем 09–12.
-- Вопросы ищутся по полному тексту; заполняются только пустые option_notes, повторный запуск безопасен.

BEGIN;

UPDATE questions q SET option_notes = n.notes::jsonb
FROM (VALUES
    ('В какой схеме находятся таблицы и представления системного каталога?', '{"A":"Это схема стандарта SQL — представления поверх pg_catalog.","B":"Схема для пользовательских объектов.","C":"Основная схема системного каталога.","D":"Схема toast-таблиц."}'),
    ('Чем information_schema отличается от pg_catalog?', '{"A":"Определена стандартом SQL и поэтому переносимее, хотя реализации в разных СУБД могут различаться.","B":"Она описывает объекты, а не хранит их данные.","C":"Доступна всем и показывает объекты, к которым есть доступ.","D":"Это схема внутри каждой базы данных."}'),
    ('Что из перечисленного — общий для всего кластера объект системного каталога?', '{"A":"Своя таблица в каждой базе.","B":"Общая таблица в pg_global, видна из любой базы.","C":"Своя таблица в каждой базе.","D":"Своя таблица в каждой базе."}'),
    ('С какого префикса начинаются имена таблиц системного каталога?', '{"A":"Такого префикса в PostgreSQL нет.","B":"Это начало имени схемы information_schema.","C":"Такого префикса нет.","D":"Все таблицы и представления каталога начинаются с pg_."}'),
    ('Как обычно устроены имена столбцов в таблицах системного каталога?', '{"A":"Префикс pg_ у имён таблиц, а не столбцов.","B":"Имена в каталоге в нижнем регистре.","C":"Такие имена используются в information_schema.","D":"Например, у pg_database столбцы datname и datdba."}'),
    ('В каком регистре системный каталог хранит имена объектов, указанных без двойных кавычек?', '{"A":"Так требует стандарт SQL, а PostgreSQL приводит к нижнему.","B":"Имена без кавычек приводятся к нижнему регистру.","C":"Так сохраняются только имена в двойных кавычках.","D":"Хранится одно имя."}'),
    ('Что представляет собой тип данных oid?', '{"A":"Около 4 млрд значений.","B":"Тип oid 32-битный.","C":"Имя хранится в отдельных столбцах, например relname.","D":"UUID — другой тип данных."}'),
    ('Для чего нужны типы reg*, например regclass?', '{"A":"Для регулярных выражений есть операторы ~ и функции regexp_*.","B":"Расширения устанавливает CREATE EXTENSION.","C":"Например, regclass для отношений, regproc для функций.","D":"Привилегии хранятся в столбцах типа aclitem[]."}'),
    ('С каких символов обычно начинаются команды psql для просмотра системного каталога?', '{"A":"Подключение к другой базе.","B":"От describe: \\dt, \\dv, \\dn и другие.","C":"Переключает расширенный формат вывода.","D":"Показывает историю команд."}'),
    ('Чем вывод команды \d+ отличается от \d?', '{"A":"Системные объекты добавляет модификатор S.","B":"Привилегии показывает \\dp.","C":"Команды \\d выполняют запросы к каталогу, но ANALYZE не запускают.","D":"Например, описание, размер и параметры хранения."}'),
    ('Какие таблицы системного каталога общие для всего кластера?', '{"A":"Своя таблица в каждой базе.","B":"Базы данных описаны в общей таблице.","C":"Своя таблица в каждой базе.","D":"Роли общие для всего кластера."}'),
    ('Что верно для схемы information_schema?', '{"A":"Её состав задан стандартом SQL.","B":"Доступна всем пользователям.","C":"Её структура определена стандартом и меняется редко.","D":"Специфику PostgreSQL отражает только pg_catalog."}'),
    ('Что верно для типа данных oid?', '{"A":"Хранит число, а не имя.","B":"У большинства таблиц каталога первичный ключ — столбец oid.","C":"Тип oid 32-битный.","D":"Около 4 млрд значений."}'),
    ('Допишите запрос, чтобы получить oid таблицы pg_class по её имени:
```
SELECT ___::regclass::oid;
```', '{"A":"Двойные кавычки задают идентификатор: получится обращение к столбцу.","B":"Без кавычек это имя столбца, а не строка.","C":"Здесь pg_class тоже воспринимается как имя столбца.","D":"Строка приводится к regclass, затем к oid."}'),
    ('Допишите запрос, чтобы выбрать только обычные таблицы:
```
SELECT relname FROM pg_class WHERE relkind = ___;
```', '{"A":"Представление.","B":"Обычная таблица.","C":"Индекс.","D":"Toast-таблица."}'),
    ('Допишите команду psql, чтобы увидеть подробное описание представления вместе с текстом запроса:
```
\d___ pg_views
```', '{"A":"Такого модификатора нет.","B":"Для представления показывает и текст запроса.","C":"Добавляет системные объекты в списки, подробностей не даёт.","D":"\\dx — другая команда, список расширений."}'),
    ('Для чего служат табличные пространства?', '{"A":"Логическое разделение — это схемы.","B":"Права задаются привилегиями.","C":"Кодировка задаётся для базы данных.","D":"По сути, это указание на каталог."}'),
    ('Какие табличные пространства создаются при инициализации кластера?', '{"A":"pg_temp — временная схема, а не табличное пространство.","B":"pg_default для баз и pg_global для общих объектов.","C":"main — имя кластера в Ubuntu, global — каталог.","D":"Это не табличные пространства; pg_wal — каталог журнала."}'),
    ('Что хранится в табличном пространстве pg_global?', '{"A":"Объекты template1 изначально лежат в pg_default.","B":"Временные таблицы — в явно указанном ТП, в temp_tablespaces или в ТП базы по умолчанию.","C":"Например, базы данных, роли и табличные пространства.","D":"Журнал находится в PGDATA/pg_wal."}'),
    ('Где на диске находится табличное пространство pg_default?', '{"A":"Данные разложены по подкаталогам баз.","B":"Это pg_global.","C":"Здесь ссылки на пользовательские табличные пространства.","D":"Такого каталога нет."}'),
    ('Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства?', '{"A":"Ссылка с именем-oid ведёт на каталог табличного пространства.","B":"Данные хранятся в каталоге ТП, без копий.","C":"Отдельный файл не создаётся; параметры ТП хранятся в pg_tablespace.","D":"Архив WAL с табличными пространствами не связан."}'),
    ('Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', '{"A":"Два кластера одной версии в одном каталоге ТП работать не могут.","B":"Журнал в табличном пространстве не хранится.","C":"Старая и новая версии могут временно жить в одном каталоге, например при pg_upgrade.","D":"Подкаталоги баз находятся уже внутри него."}'),
    ('Может ли одна база данных хранить объекты в нескольких табличных пространствах?', '{"A":"Можно и в нескольких.","B":"Место хранения указывают при создании объекта.","C":"Владелец базы здесь роли не играет.","D":"В других ТП можно размещать и постоянные таблицы, и индексы."}'),
    ('Где хранятся объекты системного каталога конкретной базы данных?', '{"A":"В pg_global только общие для кластера объекты.","B":"Такого табличного пространства нет; pg_catalog — это схема.","C":"Там только ссылки на табличные пространства.","D":"Пользовательские объекты при этом могут лежать и в других ТП."}'),
    ('Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', '{"A":"pg_global только для общих объектов.","B":"Порядок создания табличных пространств роли не играет.","C":"База получает табличное пространство шаблона.","D":"У базы всегда есть табличное пространство по умолчанию."}'),
    ('Какой сценарий типичен для табличных пространств?', '{"A":"Данные размещаются на дисках разной скорости.","B":"Права задаются привилегиями.","C":"Версии строк лежат в той же таблице.","D":"К репликации это не относится."}'),
    ('Что верно для табличного пространства по умолчанию баз данных, созданных при инициализации кластера?', '{"A":"Если не указано другое и не задан default_tablespace.","B":"pg_global — для общих объектов кластера.","C":"У баз после инициализации это pg_default.","D":"Можно изменить командой ALTER DATABASE ... SET TABLESPACE."}'),
    ('Что верно для табличных пространств?', '{"A":"Пустое табличное пространство удаляет DROP TABLESPACE.","B":"Отдельные объекты можно размещать в других ТП.","C":"Схема — логическое понятие, табличное пространство — физическое.","D":"Табличное пространство не принадлежит одной базе."}'),
    ('Где на диске находятся стандартные табличные пространства?', '{"A":"Общие объекты кластера.","B":"Каталог пользовательского ТП задаётся в LOCATION, обычно вне PGDATA; в pg_tblspc на него ссылка.","C":"pg_tblspc содержит ссылки на пользовательские ТП.","D":"Каталоги баз данных по умолчанию."}'),
    ('Допишите команду создания табличного пространства:
```
CREATE TABLESPACE ts ___ ''/var/lib/postgresql/ts_dir'';
```', '{"A":"Такого слова в команде нет.","B":"Такого слова в команде нет.","C":"Каталог табличного пространства.","D":"Такого слова в команде нет."}'),
    ('Допишите команду, чтобы создать таблицу в табличном пространстве ts:
```
CREATE TABLE t (id int) ___ ts;
```', '{"A":"Используется при создании табличного пространства.","B":"Такого варианта нет.","C":"Такого варианта нет.","D":"Таблица будет создана в ts."}'),
    ('Допишите команду, чтобы задать стоимость произвольного чтения страницы для табличного пространства:
```
ALTER TABLESPACE pg_default SET (___ = 1.1);
```', '{"A":"Оценка стоимости произвольного чтения для планировщика.","B":"Такого параметра нет; есть seq_page_cost.","C":"Такого параметра нет.","D":"Для табличного пространства не задаётся."}'),
    ('Какого размера достигает файл слоя, прежде чем создаётся следующий сегмент?', '{"A":"Размер сегмента по умолчанию.","B":"Это размер страницы по умолчанию.","C":"Это размер сегмента WAL по умолчанию.","D":"Не по умолчанию; такой размер можно задать только при сборке."}'),
    ('Как изменить предельный размер сегмента файла данных?', '{"A":"Параметр segment_size только показывает размер, заданный при сборке; изменить его нельзя.","B":"ALTER SYSTEM не меняет параметр segment_size: он только для чтения.","C":"Размер задаётся при сборке.","D":"У initdb такого ключа нет; --wal-segsize меняет сегмент журнала, а не данных."}'),
    ('Для каких объектов существует слой инициализации (init)?', '{"A":"Обычным журналируемым таблицам он не нужен.","B":"Временным таблицам он не нужен.","C":"Не только для индексов.","D":"По нему объект после сбоя возвращается в начальное состояние: таблица пустая, последовательность с начальным значением."}'),
    ('Какой суффикс у файлов карты свободного пространства?', '{"A":"Это карта видимости.","B":"Free space map.","C":"Это слой инициализации.","D":"Такого суффикса нет."}'),
    ('Сколько файлов обычно соответствует небольшой таблице?', '{"A":"Кроме основного слоя есть карты.","B":"Карта видимости обычно появляется после первой очистки.","C":"После очистки файлов обычно три.","D":"Слой init есть только у нежурналируемых таблиц."}'),
    ('Что происходит с нежурналируемой таблицей после сбоя?', '{"A":"Изменения такой таблицы в журнал не пишутся.","B":"Определение таблицы сохраняется.","C":"Ничего не помечается.","D":"Таблица остаётся, но без данных."}'),
    ('Что такое TOAST?', '{"A":"Журнал — это WAL.","B":"Это не тип индекса.","C":"Так длинные значения не мешают версии строки поместиться на страницу.","D":"Это не утилита."}'),
    ('В какой схеме находятся toast-таблицы?', '{"A":"Для временных таблиц — pg_toast_temp_N.","B":"Схема системного каталога.","C":"Схема пользовательских объектов.","D":"Временная схема; toast временных таблиц — в pg_toast_temp_N."}'),
    ('Что показывает функция pg_table_size?', '{"A":"Так работает pg_relation_size без второго аргумента.","B":"Это pg_total_relation_size.","C":"Это pg_indexes_size.","D":"Все слои таблицы и её toast-часть."}'),
    ('Какая функция показывает полный размер таблицы вместе со всеми индексами?', '{"A":"Размер одного слоя.","B":"Таблица, toast-часть и все индексы.","C":"Без индексов самой таблицы (индекс toast-таблицы учитывается).","D":"Только индексы."}'),
    ('Какие слои есть у обычной небольшой таблицы?', '{"A":"Только у нежурналируемых объектов.","B":"Обычно появляется после первой очистки.","C":"Есть у таблиц и у большинства индексов.","D":"Сами версии строк."}'),
    ('Что верно для TOAST?', '{"A":"Версия строки всегда помещается на одну страницу.","B":"Если длинное поле не нужно запросу, toast-таблица не читается.","C":"Toast-таблицы лежат в pg_toast, у временных таблиц — в pg_toast_temp_N.","D":"При стратегии extended сначала пробуется сжатие, затем вынос."}'),
    ('Какие функции учитывают размер toast-части таблицы?', '{"A":"Размер одного слоя, без toast-части.","B":"Таблица вместе с toast-частью.","C":"Ещё и индексы.","D":"Только индексы."}'),
    ('Допишите команду, чтобы создать таблицу, изменения которой не пишутся в журнал предзаписи и которая видна всем сеансам:
```
CREATE ___ TABLE t (id int);
```', '{"A":"Такого слова нет.","B":"Такого слова нет.","C":"Такого слова нет.","D":"Нежурналируемая таблица; временная тоже не журналируется, но видна только своему сеансу."}'),
    ('Допишите вызов, чтобы получить размер карты видимости таблицы:
```
SELECT pg_relation_size(''t'', ___);
```', '{"A":"Карта видимости.","B":"Основной слой.","C":"Карта свободного пространства.","D":"Такого имени слоя нет."}'),
    ('Допишите команду, чтобы длинные значения выносились в TOAST без сжатия:
```
ALTER TABLE t ALTER COLUMN body SET STORAGE ___;
```', '{"A":"Сжатие и вынос.","B":"Вынос без сжатия.","C":"Сжатие, вынос только в крайнем случае.","D":"Без сжатия и выноса."}'),
    ('Какой параметр задаёт имя экземпляра, видимое в списке процессов ОС?', '{"A":"Имя приложения клиента, видно в pg_stat_activity.","B":"Имя добавляется к названиям процессов сервера.","C":"Включает показ состояния процесса в его имени.","D":"Адреса, на которых сервер принимает подключения."}'),
    ('Какое представление показывает текущие активности всех обслуживающих и фоновых процессов?', '{"A":"Накопленная статистика по запросам.","B":"Статистика по базам данных.","C":"Параметры конфигурации.","D":"По строке на процесс: состояние, ожидания, текущий или последний запрос."}'),
    ('Что происходит с накопительной статистикой при аварийной остановке сервера?', '{"A":"Статистика хранится в общей памяти и при сбое теряется.","B":"Так бывает при штатной остановке.","C":"Статистика в журнал предзаписи не пишется.","D":"В журнал сообщений статистика не копируется."}'),
    ('Какое значение параметра stats_fetch_consistency используется по умолчанию?', '{"A":"Без кеширования.","B":"Кеширует всю статистику базы до конца транзакции.","C":"Кеширует статистику каждого запрошенного объекта.","D":"Такого значения нет."}'),
    ('Какой из параметров сбора статистики выключен по умолчанию?', '{"A":"Включён по умолчанию.","B":"Включён по умолчанию.","C":"Выключен из-за возможных накладных расходов на замер времени.","D":"Включён по умолчанию (кроме Windows)."}'),
    ('За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', '{"A":"Обычный VACUUM и автоочистка.","B":"Для ANALYZE — pg_stat_progress_analyze.","C":"Для CREATE INDEX — pg_stat_progress_create_index.","D":"Для COPY — pg_stat_progress_copy."}'),
    ('Какое расширение собирает статистику по выполняемым запросам?', '{"A":"Статистика по версиям строк и свободному месту.","B":"Показывает содержимое буферного кеша.","C":"Стороннее расширение, собирает статистику ожиданий.","D":"Число вызовов, время, строки для каждого запроса."}'),
    ('Какой параметр включает коллектор сообщений?', '{"A":"Задаёт приёмники журнала.","B":"Включает отдельный процесс, который пишет журнал в файлы.","C":"Записывает тексты команд.","D":"Минимальный уровень записываемых сообщений."}'),
    ('Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', '{"A":"Эти форматы пишет только коллектор.","B":"syslog — отдельный приёмник.","C":"Операционная система роли не играет.","D":"pgBadger анализирует журнал, для записи он не нужен."}'),
    ('Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', '{"A":"Записывает время всех команд.","B":"Записывает текст команд выбранных типов.","C":"Записывает команды не короче порога; 0 — все, -1 — отключено.","D":"Записывает долгие ожидания блокировок."}'),
    ('Какие параметры сбора статистики включены по умолчанию?', '{"A":"Выключен по умолчанию.","B":"Выключен по умолчанию.","C":"Нужен автоочистке.","D":"Включает отслеживание текущих команд сеансов в pg_stat_activity."}'),
    ('Каким приёмникам журнала сообщений нужен включённый коллектор?', '{"A":"Работает и без коллектора: сообщения идут в стандартный поток ошибок.","B":"Сообщения передаются демону syslog.","C":"Пишет только коллектор.","D":"Пишет только коллектор."}'),
    ('Какие расширения входят в поставку PostgreSQL?', '{"A":"Модуль из поставки (contrib).","B":"Модуль из поставки (contrib).","C":"Стороннее расширение.","D":"Стороннее расширение."}'),
    ('Допишите запрос, чтобы увидеть текущие активности сеансов:
```
SELECT pid, state, query FROM ___;
```', '{"A":"Текущие активности процессов.","B":"Параметры конфигурации.","C":"Накопленная статистика по запросам, а не текущие активности.","D":"Блокировки, без текста запросов."}'),
    ('Допишите команду, чтобы в журнал попадали команды, выполнявшиеся дольше секунды:
```
ALTER SYSTEM SET ___ = ''1s'';
SELECT pg_reload_conf();
